sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   //Type appropriate comment here, and begin script below
    var mfirstreportedbytask = g_form.getValue('sys_display.original.problem.first_reported_by_task');
    var ga = new GlideAjax('mdssgetlocation');
    ga.addParam('sysparm_name', 'getLocation');
    ga.addParam('sysparm_num', mfirstreportedbytask);
	// alert(mfirstreportedbytask);
    ga.getXMLAnswer(echoCallBack);

    function echoCallBack(answer) {
        g_form.addInfoMessage(
            'Incident"s state from server using getXMLAnswer: ' + answer);

    }

}
